defense.vulnerable_config:
# named.conf - unrestricted zone transfer
zone "megacorpone.com" {
  type master;
  allow-transfer { any; };  // DANGEROUS - anyone can AXFR
};

defense.secure_config:
# named.conf - restrict AXFR to secondary nameservers only
zone "megacorpone.com" {
  type master;
  allow-transfer { 192.168.1.2; };  // only your secondary NS
};
